#!/usr/bin/env python3
"""
fix_precon_acts.py — adds the Romeo & Juliet and Great Gatsby Act cards and
their climax-gate questions to src/game.src.html.

WHAT IT CHANGES
  1. DATA.acts: +15 Act cards (7 Romeo & Juliet, 8 Gatsby), generated from the
     catalog's Characters sheet (Act rows) — not retyped.  The 8 precon Act
     cards ship in the default decks; the other 7 are marked starter:false so
     they're available in the deck builder but not auto-added.
  2. DATA.actGate: climax questions for romeojuliet (3) and gatsby (5), from the
     catalog's Climax Gate Trivia sheet.
  3. actStarter(): skips Act cards marked starter:false (Macbeth's are unmarked,
     so its default deck is unchanged).
  4. actGateModal(): the header and prompt show the Act card's own number.  It
     said "ACT III" for every climax card, which mislabels the climax-gated
     Act II finals (Prince of Cats, Fallen Ashes, Tragic Avenger).

KNOWN GAP (next patch: fix_act_passives.py)
  Act passives other than "can't be healed" / "+20 below half HP" are text only
  until fix_act_passives.py wires them.  Don't publish between the two patches.

USAGE (repo root):   python3 fix_precon_acts.py      then   python3 build.py
Writes src/game.src.html.bak first.  Refuses to run twice.
"""
import os, shutil, sys

SRC = os.path.join('src', 'game.src.html')
ACTS_JS = "    { id:\"romeo_husband_of_juliet\", deck:\"romeojuliet\", act:2, from:\"romeo\", base:[\"romeojuliet\", \"romeo\"], plot:\"hit\",\n      name:\"Husband of Juliet\", hp:100, archetype:\"Outlaw\", accent:\"#3B5BA5\",\n      atk:{n:\"Love's Light Wings\", t:\"“With love's light wings did I o'erperch these walls.” Inflict 🪢 Tear.\", cost:3, dmg:50, inflict:\"tear\", label:\"50/3\"},\n      blk:{n:\"Stony Limits\", t:\"“Some consequence yet hanging in the stars.” 🪃 Riposte — while charged, attackers take 20.\", cost:2, block:30, riposte:{dmg:20, mode:\"hp\"}, label:\"30/2\"} },\n    { id:\"romeo_fortunes_fool\", deck:\"romeojuliet\", act:3, from:\"romeo_husband_of_juliet\", base:[\"romeojuliet\", \"romeo\"], plot:\"climaxQ\", resolution:\"tragic\",\n      name:\"Fortune's Fool\", hp:130, archetype:\"Martyr\", accent:\"#3B5BA5\",\n      atk:{n:\"I Defy You, Stars\", t:\"“Then I defy you, stars!” Strikes first.\", cost:4, dmg:70, flags:[\"first\"], label:\"70/4\"},\n      blk:{n:\"A Desperate Man\", t:\"“Tempt not a desperate man.” Negate the attack entirely, but every use costs 1 more ABC than the last, up to 4.\", cost:3, blockType:\"negate\", escalate:{step:1, cap:4}, label:\"X/3+\"},\n      passive:{id:\"headlong\", name:\"Headlong\", text:\"Deals +20 on the turn it evolves or enters play. Caveat: it takes 10 recoil damage with every attack.\", entryAtkAdd:20, recoil:10} },\n    { id:\"juliet_wife_of_romeo\", deck:\"romeojuliet\", act:2, from:\"juliet\", base:[\"romeojuliet\", \"juliet\"], plot:\"hit\",\n      name:\"Wife of Romeo\", hp:130, archetype:\"Sentinel\", accent:\"#C4344E\",\n      atk:{n:\"Boundless as the Sea\", t:\"“My bounty is as boundless as the sea, my love as deep.” +10 ⚔ for every Attack ABC charged.\", cost:3, dmg:40, dmgType:\"perABC\", step:10, label:\"40+/3\"},\n      blk:{n:\"Serpent Heart\", t:\"“O serpent heart, hid with a flowering face!” Inflict 🔥 Burn on the attacker.\", cost:2, block:30, inflictAtt:\"burn\", label:\"30/2\"} },\n    { id:\"juliet_o_happy_dagger\", deck:\"romeojuliet\", act:3, from:\"juliet_wife_of_romeo\", base:[\"romeojuliet\", \"juliet\"], plot:\"climaxQ\", resolution:\"tragic\", starter:false,\n      name:\"O Happy Dagger\", hp:150, archetype:\"Martyr\", accent:\"#C4344E\",\n      atk:{n:\"A Story of More Woe\", t:\"“What must be shall be.” +5 ⚔ for every ⚔ and ⛊ card in your discard pile, to +40.\", cost:3, dmg:20, pileScale:{counts:[\"atk\", \"blk\"], step:5, cap:40}, label:\"20+/3\"},\n      blk:{n:\"What Must Be\", t:\"“O happy dagger, this is thy sheath; there rust, and let me die.” Grant 📕 Hardcover.\", cost:2, block:30, grant:\"hardcover\", label:\"30/2\"},\n      passive:{id:\"her_own_hand\", name:\"Her Own Hand\", text:\"Deals +20 while it carries a negative status. Caveat: it can never clear a status from itself.\", statusedAtkAdd:20, noSelfCleanse:true} },\n    { id:\"mercutio_worms_meat\", deck:\"romeojuliet\", act:2, from:\"mercutio\", base:[\"romeojuliet\", \"mercutio\"], plot:\"hit\", resolution:\"tragic\",\n      name:\"Worms' Meat\", hp:100, archetype:\"Shadow\", accent:\"#D4A017\",\n      atk:{n:\"Scratch, a Scratch\", t:\"“If love be blind, love cannot hit the mark.” Inflict 🔥 Burn or 🫟 Spill — your choice.\", cost:3, dmg:50, inflictChoice:[\"burn\", \"spill\"], label:\"50/3\"},\n      blk:{n:\"Ask for Me Tomorrow\", t:\"“If love be rough with you, be rough with love.” Clear 🔥 Burn.\", cost:2, block:30, blockType:\"cleanse\", blkCleanse:\"burn\", label:\"30/2\"},\n      passive:{id:\"grave_man\", name:\"Grave Man\", text:\"Attacks that give a bad status deal +10. Caveat: this card carries a permanent, uncleansable 🫟 Spill (−10 HP each turn).\"} },\n    { id:\"tybalt_the_prince_of_cats\", deck:\"romeojuliet\", act:2, from:\"tybalt\", base:[\"romeojuliet\", \"tybalt\"], plot:\"climaxQ\", resolution:\"tragic\", starter:false,\n      name:\"The Prince of Cats\", hp:120, archetype:\"Gatekeeper\", accent:\"#8C1C2B\",\n      atk:{n:\"Have At Thee\", t:\"“What, drawn, and talk of peace? I hate the word.” Strikes first.\", cost:3, dmg:50, flags:[\"first\"], label:\"50/3\"},\n      blk:{n:\"Thou Wretched Boy\", t:\"“Thou, wretched boy, that didst consort him here, shalt with him hence.” Grant 🛡️ Laminate.\", cost:2, block:30, grant:\"laminate\", label:\"30/2\"},\n      passive:{id:\"king_of_cats\", name:\"King of Cats\", text:\"This card's moves cost 1 less ABC (minimum 1). Caveat: it can never be healed above its starting health.\"} },\n    { id:\"capulets_the_reconciled\", deck:\"romeojuliet\", act:2, from:\"capulets\", base:[\"romeojuliet\", \"capulets\"], plot:\"hit\", resolution:\"comic\", starter:false,\n      name:\"The Reconciled\", hp:160, archetype:\"Sentinel\", accent:\"#A3202F\",\n      atk:{n:\"Poor Sacrifices\", t:\"“Some grief shows much of love, but much of grief shows still some want of wit.” The target's next attack deals 20 less.\", cost:3, dmg:40, weaken:20, label:\"40/3\"},\n      blk:{n:\"Bury Our Strife\", t:\"“Death lies on her like an untimely frost upon the sweetest flower of all the field.” Clear one negative status from every ally.\", cost:2, block:30, teamCleanse:true, label:\"30/2\"},\n      passive:{id:\"golden_statues\", name:\"Golden Statues\", text:\"Heals 10 HP at the start of each of your turns. Caveat: it can never deal more than 40 damage in one attack.\"} },\n    { id:\"gatsby_the_host_of_west_egg\", deck:\"gatsby\", act:2, from:\"gatsby\", base:[\"gatsby\", \"gatsby\"], plot:\"hit\",\n      name:\"The Host of West Egg\", hp:140, archetype:\"Trickster\", accent:\"#3E8E7E\",\n      atk:{n:\"Dispensing Starlight\", t:\"“I tried very hard to die, but I seemed to bear an enchanted life.” Heal 20 HP.\", cost:3, dmg:60, heal:20, label:\"60/3\"},\n      blk:{n:\"That Rare Smile\", t:\"“He had waited five years and bought a mansion where he dispensed starlight to casual moths.” Clear 🔥 Burn and 🪢 Tear.\", cost:2, block:30, blockType:\"cleanse\", blkCleanse:[\"burn\", \"tear\"], label:\"30/2\"} },\n    { id:\"gatsby_doomed_dreamer\", deck:\"gatsby\", act:3, from:\"gatsby_the_host_of_west_egg\", base:[\"gatsby\", \"gatsby\"], plot:\"climaxQ\", resolution:\"tragic\",\n      name:\"Doomed Dreamer\", hp:160, archetype:\"Martyr\", accent:\"#3E8E7E\",\n      atk:{n:\"The Green Light\", t:\"“His dream must have seemed so close that he could hardly fail to grasp it.” Ignores the target's defensive buffs.\", cost:3, dmg:60, ignoreDefBuffs:true, label:\"60/3\"},\n      blk:{n:\"One Fine Morning\", t:\"“Can't repeat the past? Why of course you can!” Draw 1.\", cost:2, block:40, onBlockDraw:1, label:\"40/2\"},\n      passive:{id:\"platonic_conception\", name:\"Platonic Conception\", text:\"You may look at the top card of your deck at any time. Caveat: when this card is knocked out you discard a random card.\"} },\n    { id:\"nick_the_reluctant_confidant\", deck:\"gatsby\", act:2, from:\"nick\", base:[\"gatsby\", \"nick\"], plot:\"hit\", starter:false,\n      name:\"The Reluctant Confidant\", hp:140, archetype:\"Gatekeeper\", accent:\"#5C7CA6\",\n      atk:{n:\"Nothing Is Yours\", t:\"“I was within and without, simultaneously enchanted and repelled.” Remove the target's ✨ Highlight.\", cost:2, dmg:30, stripPos:\"highlight\", label:\"30/2\"},\n      blk:{n:\"Read the Room\", t:\"“There are only the pursued, the pursuing, the busy and the tired.” Draw 1.\", cost:2, block:40, onBlockDraw:1, label:\"40/2\"} },\n    { id:\"nick_westward_traveler\", deck:\"gatsby\", act:3, from:\"nick_the_reluctant_confidant\", base:[\"gatsby\", \"nick\"], plot:\"climaxQ\", resolution:\"comic\", starter:false,\n      name:\"Westward Traveler\", hp:170, archetype:\"Inquisitor\", accent:\"#5C7CA6\",\n      atk:{n:\"Answer in Kind\", t:\"“Human sympathy has its limits.” +5 ⚔ per ⚔ and ⛊ card in your discard pile, to +40.\", cost:3, dmg:20, pileScale:{counts:[\"atk\", \"blk\"], step:5, cap:40}, label:\"20+/3\"},\n      blk:{n:\"The Price of Touching\", t:\"“Reserving judgments is a matter of infinite hope.” 🪃 Riposte — while charged, attackers take 20.\", cost:2, block:30, riposte:{dmg:20, mode:\"hp\"}, label:\"30/2\"},\n      passive:{id:\"so_we_beat_on\", name:\"So We Beat On\", text:\"When an ally is knocked out, attach 1 ABC from your discard pile to this card free of trivia. Caveat: it cannot block on the turn it evolves.\", onAllyKO:{attachFromDiscard:1}, noBlockOnEvolve:true} },\n    { id:\"daisy_the_golden_girl\", deck:\"gatsby\", act:2, from:\"daisy\", base:[\"gatsby\", \"daisy\"], plot:\"hit\",\n      name:\"The Golden Girl\", hp:120, archetype:\"Innocent\", accent:\"#C9A24B\",\n      atk:{n:\"Still Here\", t:\"“I hope she'll be a fool. That's the best thing a girl can be in this world.” Heal 20 HP.\", cost:3, dmg:50, heal:20, label:\"50/3\"},\n      blk:{n:\"Clean and Whole\", t:\"“Oh, you want too much! I love you now; isn't that enough?” Clear 🔥 Burn and 🪢 Tear.\", cost:2, block:30, blockType:\"cleanse\", blkCleanse:[\"burn\", \"tear\"], label:\"30/2\"} },\n    { id:\"daisy_careless_fool\", deck:\"gatsby\", act:3, from:\"daisy_the_golden_girl\", base:[\"gatsby\", \"daisy\"], plot:\"climaxQ\", resolution:\"tragic\", starter:false,\n      name:\"Careless Fool\", hp:150, archetype:\"Fallen\", accent:\"#C9A24B\",\n      atk:{n:\"Given Time\", t:\"“All the bright precious things fade so fast, and they don't come back.” +10 each turn it stays in play.\", cost:3, dmg:50, dmgType:\"perTurn\", step:10, base:50, label:\"50+/3\"},\n      blk:{n:\"Wipe It Clean\", t:\"“They're such beautiful shirts.” Clear 🫆 Smudge.\", cost:2, block:30, blockType:\"cleanse\", blkCleanse:\"smudge\", label:\"30/2\"},\n      passive:{id:\"given_time\", name:\"Given Time\", text:\"Whoever attacks this card takes 20 damage. Caveat: it loses 10 HP each time that happens.\"} },\n    { id:\"myrtle_fallen_ashes\", deck:\"gatsby\", act:2, from:\"myrtle\", base:[\"gatsby\", \"myrtle\"], plot:\"climaxQ\", resolution:\"tragic\", starter:false,\n      name:\"Fallen Ashes\", hp:110, archetype:\"Martyr\", accent:\"#B0556B\",\n      atk:{n:\"The Reckoning\", t:\"Some things...you just don't see coming. +10 each turn it stays in play.\", cost:4, dmg:70, dmgType:\"perTurn\", step:10, base:70, label:\"70+/4\"},\n      blk:{n:\"Sealed Over\", t:\"\\\"This is a valley of ashes, where ashes grow like wheat into ridges and hills.\\\" Grant 🛡️ Laminate.\", cost:3, block:50, blockType:\"laminate\", label:\"50/3\"},\n      passive:{id:\"cursed_crown\", name:\"Cursed Crown\", text:\"Whoever knocks it out takes 40 damage. Caveat: it cannot block on the turn it attacks.\"} },\n    { id:\"george_tragic_avenger\", deck:\"gatsby\", act:2, from:\"george\", base:[\"gatsby\", \"george\"], plot:\"climaxQ\", resolution:\"tragic\",\n      name:\"Tragic Avenger\", hp:160, archetype:\"Force of Nature\", accent:\"#8A8170\",\n      atk:{n:\"Vengeful Shot\", t:\"God's Retribution is worth the price. Costs 10 of your own HP.\", cost:4, dmg:90, sacrifice:10, label:\"90/4\"},\n      blk:{n:\"Endurance Shield\", t:\"A man can only take but so much... +10 each of your turns it stays in play.\", cost:3, block:30, blockType:\"perTurn\", base:30, step:10, label:\"30+/3\"},\n      passive:{id:\"the_eyes_of_t_j_eckleburg\", name:\"The Eyes of T. J. Eckleburg\", text:\"Attacks deal +30 against the character that knocked out Myrtle Wilson. Caveat: it can never be healed.\", vsKillerOf:\"myrtle\", dmgAdd:30, noHeal:true} }"
GATES_JS = "  D.actGate.romeojuliet = [\n    { tag:\"climax\", q:\"How does Romeo's fatalism actively accelerate his tragic outcome?\", opts:[\"He waits passively for the Prince's execution order.\", \"Believing he is \\\"fortune's fool,\\\" he acts recklessly without verifying facts.\", \"He refuses to duel Tybalt, causing Mercutio to disown him.\", \"He challenges the Montague family leadership directly.\"], ans:1 },\n    { tag:\"climax\", q:\"How does Juliet’s agency shift over the course of the play?\", opts:[\"From passive obedience to radical self-determination.\", \"From rebellious independence to relying on the Nurse.\", \"From romance to seeking refuge in a convent.\", \"From loving Romeo to agreeing to marry Paris.\"], ans:0 },\n    { tag:\"climax\", q:\"Why is Tybalt's duel in Act III the turning point of the play?\", opts:[\"It ends the feud between the two houses.\", \"Tybalt kills Mercutio, Romeo kills Tybalt, and Romeo is banished.\", \"It convinces Capulet to cancel Juliet's wedding.\", \"The Prince names Tybalt heir of Verona.\"], ans:1 }\n  ];\n  D.actGate.gatsby = [\n    { tag:\"climax\", q:\"What primary delusion drives Gatsby's ultimate downfall?\", opts:[\"Inability to repay debts to Meyer Wolfsheim.\", \"His insistence on repeating the past and recreating his ideal image of Daisy.\", \"Betrayal by Nick Carraway in court.\", \"Lack of monetary wealth compared to Tom Buchanan.\"], ans:1 },\n    { tag:\"climax\", q:\"How does Nick’s stance as an \\\"objective narrator\\\" collapse by the end of the novel?\", opts:[\"He publishes a gossip book about West Egg.\", \"Disgusted by the elite's moral carelessness, he judges them and moves West.\", \"He is arrested as an accomplice to bootlegging.\", \"He takes over Gatsby's mansion and fortune.\"], ans:1 },\n    { tag:\"climax\", q:\"How does social privilege shape Daisy's resolution at the novel's climax?\", opts:[\"Forces her into exile in Europe without money.\", \"Allows her and Tom to retreat into wealth and avoid all accountability.\", \"Compels her to confess publicly to the hit-and-run.\", \"Leads her to divorce Tom and mourn Gatsby publicly.\"], ans:1 },\n    { tag:\"climax\", q:\"How does George Wilson change after Myrtle's death?\", opts:[\"He sells the garage and moves West with Nick.\", \"The exhausted, passive husband becomes a vengeful man who acts on Tom's misdirection.\", \"He forgives Daisy and reconciles with Tom.\", \"He takes over Wolfsheim's business.\"], ans:1 },\n    { tag:\"climax\", q:\"What does Myrtle's death reveal about class in the novel?\", opts:[\"That wealth protects no one in West Egg.\", \"That George is secretly wealthy.\", \"The rich escape consequences while Myrtle and George pay with their lives.\", \"That the Valley of Ashes is being rebuilt.\"], ans:2 }\n  ];"

EDITS = [
    # (label, anchor, replacement)
    ('DATA.acts — append R&J + Gatsby Act cards',
     '\n  ];\n  D.actGate = D.actGate || {};',
     ',\n' + ACTS_JS + '\n  ];\n  D.actGate = D.actGate || {};'),
    ('actStarter — skip starter:false Act cards',
     'const acts=actsForDeck(def.d).filter(function(a){ return (def.ch||[]).indexOf(a.base[1])>=0; })',
     'const acts=actsForDeck(def.d).filter(function(a){ return a.starter!==false && (def.ch||[]).indexOf(a.base[1])>=0; })'),
    ('actGateModal — show the card\'s own Act number (1/3)',
     "  const q=g.q, wrong=g.picked!=null && g.picked!==q.ans;\n",
     "  const q=g.q, wrong=g.picked!=null && g.picked!==q.ans;\n"
     "  const _ga=actById(((S.you.hand.find(function(c){ return c.cid===g.cid; }))||{}).actId)||{}, _gr=roman(_ga.act||3);\n"),
    ('actGateModal — header (2/3)',
     '<div class="tri-head">\\u2726 ACT III \\u00b7 THE CLIMAX</div>',
     '<div class="tri-head">\\u2726 ACT ${_gr} \\u00b7 THE CLIMAX</div>'),
    ('actGateModal — prompt (3/3)',
     "'Answer correctly to reach Act III. No retry.'",
     "'Answer correctly to reach Act '+_gr+'. No retry.'"),
]
GATE_ANCHOR = '    { tag:"theme", q:"How does the play treat the witches\\u2019 prophecies?"'

def main():
    if not os.path.exists(SRC): sys.exit('Run from the repo root: %s not found.' % SRC)
    s = open(SRC, encoding='utf-8').read()
    if 'romeojuliet' not in s: sys.exit('This is not the live src/game.src.html (no romeojuliet).')
    if 'romeo_husband_of_juliet' in s or 'D.actGate.gatsby' in s:
        sys.exit('Already applied (romeo_husband_of_juliet found). Nothing changed.')
    for label, a, _ in EDITS:
        n = s.count(a)
        if n != 1: sys.exit('Anchor for "%s" found %d times (need exactly 1). Nothing changed.' % (label, n))
    if s.count(GATE_ANCHOR) != 1: sys.exit('Macbeth gate anchor not found exactly once. Nothing changed.')
    for label, a, b in EDITS:
        s = s.replace(a, b, 1)
    # gates go right after the Macbeth gate array closes
    i = s.index(GATE_ANCHOR); j = s.index('\n  ];', i) + len('\n  ];')
    s = s[:j] + '\n' + GATES_JS + s[j:]
    shutil.copy2(SRC, SRC + '.bak')
    open(SRC, 'w', encoding='utf-8').write(s)
    print('fix_precon_acts: added 15 Act cards + 8 climax questions; backup at %s.bak' % SRC)
    print('Next: python3 build.py')

if __name__ == '__main__':
    main()
